// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdConfigFile 是各仓库阈值的配置，位于仓库根的 config/ 下。
const thresholdConfigFile = "config/thresholds.json"

// thresholdConfigPath 返回配置文件路径。它是变量，测试可以替换。
var thresholdConfigPath = findThresholdConfigPath

// findThresholdConfigPath 从当前目录向上找到模块根（含 go.mod 的目录），
// 再拼出 config/thresholds.json；找不到模块根时返回空串。
func findThresholdConfigPath() string {
	dir, err := os.Getwd()
	if err != nil {
		return ""
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, thresholdConfigFile)
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

// LowStockThreshold 返回这个仓库的低库存阈值：config/thresholds.json 里配了就用它，
// 没配（或文件缺失、读不出来、内容不是 JSON 对象）回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if thresholds, ok := loadThresholds(thresholdConfigPath()); ok {
		// 用 *int 区分「配了 0」和「配了 null」：后者视为未配置。
		if threshold, ok := thresholds[warehouse]; ok && threshold != nil {
			return *threshold
		}
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取并解析配置文件；只有拿到 JSON 对象时才返回 ok=true。
func loadThresholds(path string) (map[string]*int, bool) {
	if path == "" {
		return nil, false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var thresholds map[string]*int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, false
	}
	return thresholds, true
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if IsLowStock(warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}

